package com.coworkhub.controller;
import com.coworkhub.entity.*;import com.coworkhub.repository.*;import com.coworkhub.service.BookingPricingService;import org.springframework.web.bind.annotation.*;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import org.springframework.transaction.annotation.Transactional;import java.time.*;import java.math.*;import java.util.*;
@RestController @RequestMapping("/api/reservas")public class BookingController{
 private final BookingRepository bookings;private final RoomRepository rooms;private final MemberRepository members;private final AdditionalServiceRepository services;private final UserAccountRepository users;private final Clock clock;private final BookingPricingService pricing;
 public BookingController(BookingRepository b,RoomRepository r,MemberRepository m,AdditionalServiceRepository s,UserAccountRepository u,Clock c,BookingPricingService pricing){bookings=b;rooms=r;members=m;services=s;users=u;clock=c;this.pricing=pricing;}
 record Create(@jakarta.validation.constraints.NotNull Long roomId,Long memberId,@jakarta.validation.constraints.NotNull LocalDateTime startTime,@jakarta.validation.constraints.NotNull LocalDateTime endTime,@jakarta.validation.constraints.Positive int attendees,@jakarta.validation.Valid List<ServiceLine> services){ }record ServiceLine(@jakarta.validation.constraints.NotNull Long serviceId,@jakarta.validation.constraints.Positive int quantity){}record BookingView(Long id,Long roomId,String roomName,Long memberId,String memberName,LocalDateTime startTime,LocalDateTime endTime,int attendees,Enums.BookingStatus status,BigDecimal roomCost,BigDecimal servicesCost,BigDecimal totalCost,BigDecimal cancellationFee,List<ItemView> items){}record ItemView(Long serviceId,String serviceName,int quantity,BigDecimal unitPrice,BigDecimal subtotal){}
 private Long tokenMember(Authentication auth){if(auth==null)return null;var user=users.findByUsername(auth.getName()).orElseThrow();return user.member==null?null:user.member.id;}private void assertOwner(Authentication auth,Booking b){if(auth.getAuthorities().stream().anyMatch(a->a.getAuthority().equals("ROLE_ADMIN")||a.getAuthority().equals("ROLE_RECEPTIONIST")))return;Long memberId=tokenMember(auth);if(memberId==null||!memberId.equals(b.member.id))throw new org.springframework.security.access.AccessDeniedException("No puede acceder a reservas de otros miembros");}
 private BookingView view(Booking b){List<ItemView> items=b.items.stream().map(i->new ItemView(i.service.id,i.service.name,i.quantity,i.appliedUnitPrice,i.appliedUnitPrice.multiply(BigDecimal.valueOf(i.quantity)))).toList();return new BookingView(b.id,b.room.id,b.room.name,b.member.id,b.member.fullName,b.startTime,b.endTime,b.attendees,b.status,b.roomCost,b.servicesCost,b.totalCost,b.cancellationFee,items);}
 @PostMapping @PreAuthorize("hasAnyRole('ADMIN','RECEPTIONIST','MEMBER')")@Transactional public ResponseEntity<?> create(@jakarta.validation.Valid @RequestBody Create d,Authentication auth){Long memberId=d.memberId();if(auth.getAuthorities().stream().anyMatch(a->a.getAuthority().equals("ROLE_MEMBER"))){memberId=tokenMember(auth);if(d.memberId()!=null&&!d.memberId().equals(memberId))throw new org.springframework.security.access.AccessDeniedException("Un miembro solo reserva para sí mismo");}if(memberId==null)throw new IllegalArgumentException("memberId requerido");Room room=rooms.findLockedById(d.roomId()).orElseThrow();Member member=members.findById(memberId).orElseThrow();LocalDateTime now=LocalDateTime.now(clock);if(member.status!=Enums.MemberStatus.ACTIVE)throw new IllegalStateException("Miembro suspendido (RN-05)");if(d.startTime()==null||d.endTime()==null)throw new IllegalArgumentException("Fecha y hora obligatorias");Duration duration=Duration.between(d.startTime(),d.endTime());if(duration.toMinutes()<30||duration.toMinutes()>480||duration.toMinutes()%30!=0||!d.startTime().toLocalDate().equals(d.endTime().toLocalDate()))throw new IllegalStateException("Duración inválida: debe ser 30 minutos a 8 horas en intervalos de 30 (RN-02)");if(d.startTime().isBefore(now.plusHours(1)))throw new IllegalStateException("Debe reservar con una hora de anticipación (RN-03)");if(!room.active||d.attendees()<1||d.attendees()>room.capacity)throw new IllegalStateException("Sala inactiva o capacidad excedida (RN-04)");if(d.startTime().toLocalTime().isBefore(room.location.openingTime)||d.endTime().toLocalTime().isAfter(room.location.closingTime))throw new IllegalStateException("Fuera del horario de sede (RN-03)");if(!bookings.findByRoomIdAndStatusInAndStartTimeLessThanAndEndTimeGreaterThan(room.id,List.of(Enums.BookingStatus.PENDING,Enums.BookingStatus.CONFIRMED),d.endTime(),d.startTime()).isEmpty())throw new IllegalStateException("Sala ya reservada en ese horario (RN-01)");long active=bookings.countByMemberIdAndStatusInAndEndTimeAfter(member.id,List.of(Enums.BookingStatus.PENDING,Enums.BookingStatus.CONFIRMED),now);if(active>=member.plan.maxActiveBookings)throw new IllegalStateException("Límite de reservas activas del plan alcanzado (RN-06)");
 Booking b=new Booking();b.room=room;b.member=member;b.startTime=d.startTime();b.endTime=d.endTime();b.attendees=d.attendees();b.roomCost=pricing.calculateRoomCost(member,room,d.startTime(),d.endTime());b.servicesCost=BigDecimal.ZERO;if(d.services()!=null)for(ServiceLine line:d.services())addItem(b,line.serviceId(),line.quantity());b.totalCost=b.roomCost.add(b.servicesCost);Booking saved=bookings.save(b);return ResponseEntity.status(201).body(view(saved));}
 @GetMapping @Transactional @PreAuthorize("hasAnyRole('ADMIN','RECEPTIONIST','MEMBER')")public List<BookingView> all(@RequestParam(required=false) Long miembroId,@RequestParam(required=false) Long salaId,@RequestParam(required=false) LocalDate fecha,@RequestParam(required=false) Enums.BookingStatus estado,Authentication auth){List<Booking> list;if(miembroId!=null)list=bookings.findByMemberId(miembroId);else if(salaId!=null)list=bookings.findByRoomId(salaId);else if(estado!=null)list=bookings.findByStatus(estado);else list=bookings.findAllWithDetails();if(fecha!=null)list=list.stream().filter(b->b.startTime.toLocalDate().equals(fecha)).toList();if(auth.getAuthorities().stream().anyMatch(a->a.getAuthority().equals("ROLE_MEMBER"))){Long own=tokenMember(auth);if(miembroId!=null&&!miembroId.equals(own))throw new org.springframework.security.access.AccessDeniedException("No autorizado");list=list.stream().filter(b->b.member.id.equals(own)).toList();}return list.stream().map(this::view).toList();}
 @GetMapping("/{id}")@Transactional @PreAuthorize("hasAnyRole('ADMIN','RECEPTIONIST','MEMBER')")public BookingView one(@PathVariable Long id,Authentication auth){Booking b=bookings.findById(id).orElseThrow();assertOwner(auth,b);return view(b);}
 private void addItem(Booking b,Long serviceId,int quantity){if(b.status!=Enums.BookingStatus.PENDING)throw new IllegalStateException("Los servicios solo se modifican en reservas PENDING (RN-10)");if(quantity<1)throw new IllegalArgumentException("Cantidad debe ser positiva");AdditionalService s=services.findById(serviceId).orElseThrow();BookingItem item=new BookingItem();item.booking=b;item.service=s;item.quantity=quantity;item.appliedUnitPrice=s.unitPrice;b.items.add(item);recalculate(b);}
 private void recalculate(Booking b){b.servicesCost=b.items.stream().map(i->i.appliedUnitPrice.multiply(BigDecimal.valueOf(i.quantity))).reduce(BigDecimal.ZERO,BigDecimal::add);b.totalCost=b.roomCost.add(b.servicesCost);}
 @PostMapping("/{id}/servicios")@PreAuthorize("hasAnyRole('ADMIN','RECEPTIONIST','MEMBER')")@Transactional public BookingView addService(@PathVariable Long id,@jakarta.validation.Valid @RequestBody ServiceLine line,Authentication auth){Booking b=bookings.findById(id).orElseThrow();assertOwner(auth,b);addItem(b,line.serviceId(),line.quantity());return view(bookings.save(b));}
 @DeleteMapping("/{id}/servicios/{servicioId}")@PreAuthorize("hasAnyRole('ADMIN','RECEPTIONIST','MEMBER')")@Transactional public BookingView removeService(@PathVariable Long id,@PathVariable Long servicioId,Authentication auth){Booking b=bookings.findById(id).orElseThrow();assertOwner(auth,b);if(b.status!=Enums.BookingStatus.PENDING)throw new IllegalStateException("Los servicios solo se modifican en reservas PENDING (RN-10)");b.items.removeIf(i->i.service.id.equals(servicioId));recalculate(b);return view(bookings.save(b));}
 @PostMapping("/{id}/confirmar")@PreAuthorize("hasAnyRole('ADMIN','RECEPTIONIST')")@Transactional public BookingView confirm(@PathVariable Long id){Booking b=bookings.findById(id).orElseThrow();if(b.status!=Enums.BookingStatus.PENDING)throw new IllegalStateException("Transición inválida (RN-09)");b.status=Enums.BookingStatus.CONFIRMED;return view(bookings.save(b));}
 @PostMapping("/{id}/completar")@PreAuthorize("hasAnyRole('ADMIN','RECEPTIONIST')")@Transactional public BookingView complete(@PathVariable Long id){Booking b=bookings.findById(id).orElseThrow();if(b.status!=Enums.BookingStatus.CONFIRMED)throw new IllegalStateException("Transición inválida (RN-09)");b.status=Enums.BookingStatus.COMPLETED;return view(bookings.save(b));}
 @PostMapping("/{id}/cancelar")@PreAuthorize("hasAnyRole('ADMIN','RECEPTIONIST','MEMBER')")@Transactional public BookingView cancel(@PathVariable Long id,Authentication auth){Booking b=bookings.findById(id).orElseThrow();assertOwner(auth,b);if(b.status!=Enums.BookingStatus.PENDING&&b.status!=Enums.BookingStatus.CONFIRMED)throw new IllegalStateException("Solo se cancelan reservas PENDING o CONFIRMED (RN-09)");Duration remaining=Duration.between(LocalDateTime.now(clock),b.startTime);if(remaining.isNegative()||remaining.toHours()<2)throw new IllegalStateException("No se puede cancelar con menos de 2 horas o después de iniciada (RN-08)");b.cancellationFee=remaining.toHours()>=24?BigDecimal.ZERO:b.roomCost.multiply(new BigDecimal("0.50")).setScale(2,RoundingMode.HALF_UP);b.status=Enums.BookingStatus.CANCELLED;return view(bookings.save(b));}
}
